#!/bin/sh
# The odometry with loop closure on simulated worlds (generated by
# `rover-sim generate`, never used for tuning), in parallel.
#   eval/run_sim.sh [SEEDS...]   (default 2 3 4 5)
cd "$(dirname "$0")/.."
EXE=vio/build/rover-vio; [ -f vio/build/rover-vio.exe ] && EXE=vio/build/rover-vio.exe
SIM=sim/target/release/rover-sim; [ -f $SIM.exe ] && SIM=$SIM.exe
mkdir -p results/sim_vio data/sim
SEEDS=${*:-2 3 4 5}
for s in $SEEDS; do
  [ -d data/sim/world$s ] || $SIM generate data/sim/world$s --seed $s --obstacles 6 --laps 1 > /dev/null
done
for s in $SEEDS; do echo $s; done | xargs -P ${JOBS:-4} -I{} sh -c "$EXE data/sim/world{} --voc data/voc/rover.voc --json results/sim_vio/world{}.json --loops results/sim_vio/world{}_loops.txt > /dev/null 2> results/sim_vio/world{}.log"
